const lockOpenPlan = `-- name: LockOpenPlan :one
select round from app.plans where id = $1 and status = 'open' for update
`

// Locks the plan so the worker and a signup arriving at the same moment
// don't both act on a round that's being scheduled.
func (q *Queries) LockOpenPlan(ctx context.Context, id uuid.UUID) (int16, error) {
	row := q.db.QueryRow(ctx, lockOpenPlan, id)
	var round int16
	err := row.Scan(&round)
	return round, err
}

const nextPlanRound = `-- name: NextPlanRound :exec
update app.plans
set round = round + 1, window_start = $1, window_days = $2,
    signup_deadline = $3
where id = $4 and status = 'open'
`

type NextPlanRoundParams struct {
	WindowStart    pgtype.Date
	WindowDays     int16
	SignupDeadline pgtype.Timestamptz
	ID             uuid.UUID
}

func (q *Queries) NextPlanRound(ctx context.Context, arg NextPlanRoundParams) error {
	_, err := q.db.Exec(ctx, nextPlanRound,
		arg.WindowStart,
		arg.WindowDays,
		arg.SignupDeadline,
		arg.ID,
	)
	return err
}

const pickVenue = `-- name: PickVenue :one
select v.google_place_id from app.venues v join app.cities c on c.id = v.city_id
where v.area_id = $1 and v.category_id = any($2::text[]) and v.status <> 'rejected'
  and (v.status = 'approved' or not c.approved_venues_only)
order by (v.status = 'approved') desc, random()
limit 1
`

type PickVenueParams struct {
	AreaID     string
	Categories []string
}

// A venue for an activity in an area: one of its venue categories, never a
// rejected place, approved ones first (admin curation, M8), otherwise any
// candidate at random so plans in one area don't all use the same café.
// In a city that uses only approved venues (00023), never a candidate.
func (q *Queries) PickVenue(ctx context.Context, arg PickVenueParams) (string, error) {
	row := q.db.QueryRow(ctx, pickVenue, arg.AreaID, arg.Categories)
	var google_place_id string
	err := row.Scan(&google_place_id)
	return google_place_id, err
}

const upsertSignup = `-- name: UpsertSignup :exec
insert into app.plan_signups (plan_id, user_id) values ($1, $2)
on conflict (plan_id, user_id) do nothing
`

type UpsertSignupParams struct {
	PlanID uuid.UUID
	UserID uuid.UUID
}

func (q *Queries) UpsertSignup(ctx context.Context, arg UpsertSignupParams) error {
	_, err := q.db.Exec(ctx, upsertSignup, arg.PlanID, arg.UserID)
	return err
}

